<template>
  <div class="full-width">
    <div class="row">
    <div class="col-xs-6 col-sm-6 col-md-6 col-lg-6">
    </div>
    <div class="col-xs-6 col-sm-6 col-md-6 col-lg-6">
      <div class="buttons-container q-pa-sm flex justify-end">
        <f-btn
          :disable="isDefault"
          :label="$t('save')"
          @click="updateTomlConfig()"
          class="q-ml-sm q-mr-sm"
        />
        <f-btn
          :label="$t('test_export_json')"
          @click="toggleMenu()"
          class="q-mr-sm"
        />
      </div>
    </div>
  </div>
  <div class="row">
    <div
      class="white-inputs"
      :class="!showExportPanel ? 'full-width' : 'right_section-30vw'"
      id="right_section"
    >
      <q-splitter
        v-model="splitterModel"
        class="rule-management-height"
        :limits="[35, 80]"
      >
        <template v-slot:before>
          <div class="row">
            <div class="col-sm-3 col-md-3 col-lg-3 q-pa-sm">
              <q-input
                ref="nameInputRef"
                outlined
                dense
                :label="$t('name')"
                v-model="name"
                :readonly="isDefault || !!inforM3TomlMappingId"
                :rules="isNameRequired ? [val => !!val || $t('field_required')] : []"
                lazy-rules
                hide-bottom-space
              />
            </div>
            <div class="col-sm-9 col-md-9 col-lg-9 q-pa-sm">
              <q-input
                outlined
                dense
                :label="$t('description')"
                v-model="description"
                :readonly="isDefault || !!inforM3TomlMappingId"
              />
            </div>
          </div>

          <div class="add-criteria q-px-md q-pb-md q-pt-md">
            <p class="text-weight-bold text-primary font-size-16">
              {{ $t('add_rule') }}
            </p>
            <div class="row q-gutter-md">
              <q-input
                outlined
                dense
                :disable="isDefault"
                :label="$t('name')"
                v-model="rule_name"
                class="rule-manage-select"
              />

              <q-select
                outlined
                dense
                emit-value
                map-options
                :disable="isDefault"
                class="rule-manage-select"
                v-model="sectionModel"
                :options="section_options"
                :label="$t('section')"
              >
              </q-select>

              <template v-if="selectedIndex >= 0">
                <f-btn
                  :disable="isDefault"
                  :label="$t('update_rule')"
                  @click="updateRule()"
                />
                <f-btn
                  :disable="isDefault"
                  :label="$t('cancel')"
                  @click="resetModel()"
                />
              </template>
              <f-btn
                v-else
                :label="$t('add_rule')"
                @click="addRule()"
                :disable="isDefault"
              />
            </div>
            <div class="q-pt-lg">
              <q-markup-table
                flat
                class="dashboard-table-style dashboard-table-height back-white"
              >
                <thead>
                  <tr class="table-header-text">
                    <th>
                      {{ $t('active') }}
                    </th>
                    <th>
                      {{ $t('name') }}
                    </th>
                    <th>
                      {{ $t('section') }}
                    </th>

                    <th style="width: 100px">
                      {{ $t('actions') }}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <tr
                    v-for="(rule, index) in rules"
                    :key="index"
                    @click="ruleClick(rule, Number(index))"
                    class="cursor-pointer"
                    :class="selectedIndex == index ? 'highlighted-back' : ''"
                  >
                    <td>
                      <q-checkbox
                        dense
                        v-model="rule['active']"
                        :disable="isDefault"
                        @update:model-value="updateToml"
                      />
                    </td>
                    <td>{{ rule.name }}</td>
                    <td>{{ $t(rule.section) }}</td>
                    <td>
                      <q-btn
                        flat
                        dense
                        round
                        @click.stop.prevent
                        icon="more_horiz"
                      >
                        <q-menu
                          auto-close
                          transition-show="jump-down"
                          transition-hide="jump-up"
                          anchor="bottom middle"
                          self="top middle"
                        >
                          <q-list dense style="min-width: 100px">
                            <q-item
                              clickable
                              @click="removeRule(Number(index))"
                              :disable="isDefault"
                            >
                              <q-item-section
                                ><span class="text-red-14">{{
                                  $t('delete')
                                }}</span></q-item-section
                              >
                            </q-item>
                          </q-list>
                        </q-menu>
                      </q-btn>
                    </td>
                  </tr>
                </tbody>
              </q-markup-table>
            </div>
          </div>
          <q-separator class="q-my-md" />

          <MatchCriteria :isDefault="isDefault" @updateToml="updateToml" />

          <Actions :isDefault="isDefault" @updateToml="updateToml" />
        </template>
        <template v-slot:after>
          <div class="q-pa-md">
            <p class="text-weight-bold text-primary font-size-16">
              {{ $t('toml_file') }}
            </p>
            <prism-editor
              class="special-rules-editor"
              v-model="toml_rules"
              :highlight="highlighter"
              line-numbers
              :tabSize="4"
            >
            </prism-editor>
          </div>
        </template>
      </q-splitter>
    </div>
    <div
      class="back-white border-left-bdbdbd vw-30"
      id="left_section"
      v-if="showExportPanel"
    >
      <div class="scroll-area-height q-ma-sm scrolle-y">
        <div class="row">
          <q-input
            outlined
            dense
            label="Document id..."
            v-model="docId"
            class="width-320px"
          />
          <f-btn
            :disable="isDefault"
            :label="$t('test')"
            @click="loadExportJson()"
            class="margin-left-auto"
          />
        </div>

        <JsonViewer :jsonData="exportJson" />
      </div>
    </div>
  </div>
  </div>

  <Loader />
</template>

<script lang="ts">

import * as toml from 'toml';
import { storeToRefs } from 'pinia';
import Actions from './Actions.vue';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import { exportApiService } from 'src/services';
import MatchCriteria from './MatchCriteria.vue';
import helperMixin from 'src/mixins/helperMixin';
import type { dynamicObj } from 'src/pages/assets';
import stringifyToml from '@iarna/toml/stringify.js';
import { ApiExceptions } from 'src/exceptions/index';
import JsonViewer from 'src/components/JsonViewer.vue';
import { documentDetailApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import { M3_TOML_MAPPING, RULE_MANAGER } from 'src/constants';
import {
  useDocExportStore,
  useSettingStore,
  useRuleManagerStore,
} from 'src/store/main';

import { PrismEditor } from 'vue-prism-editor';
import 'vue-prism-editor/dist/prismeditor.min.css';
import { highlight, languages } from 'src/utils/prism';
export default defineComponent({
  name: 'RuleManagement',
  mixins: [helperMixin, cache],
  components: {
    Loader,
    Actions,
    JsonViewer,
    PrismEditor,
    MatchCriteria,
  },
  data() {
    return {
      id: ref(''),
      name: ref(''),
      description: ref(''),
      docId: ref(''),
      isDefault: ref(false),
    };
  },
  computed: {
    isNameRequired(): boolean {
      return !this.inforM3TomlMappingId;
    },
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == false && oldVal == true) {
          if (this.user_settings['RULE_MANAGER_MODULES_SETTINGS'] === false) {
            this.$router.go(-1);
          }
        }
      },
    },
  },
  mounted() {
    this.init();
    this.initDropDowns();
  },

  methods: {
    async init() {
      this.inforM3TomlMappingId = this.$route.params.id as string;

      if (this.inforM3TomlMappingId) {
        await this.getExportConfigurationMapping();
        return;
      }

      const cachedData = this.getDataFromSessionByKey(RULE_MANAGER);
      if (!cachedData) {
        this.$router.push('/settings/toml-samples');
      }

      this.prepareDataFromCache(cachedData);
    },
    initDropDowns() {
      this.section_options = [
        {
          label: this.$t('cost_lines'),
          value: 'cost_lines',
        },
        {
          label: this.$t('tax_lines'),
          value: 'tax_lines',
        },
        {
          label: this.$t('receipt_lines'),
          value: 'receipt_lines',
        },
        {
          label: this.$t('line_charges'),
          value: 'line_charges',
        },
        {
          label: this.$t('header_charges'),
          value: 'header_charges',
        },
      ];
    },
    prepareDataFromCache(cachedData: any) {
      this.id = cachedData.id;
      this.name = cachedData.mapping_name;
      this.isDefault = cachedData.isDefault;
      this.toml_rules = cachedData.mapping_value;
      this.description = cachedData.mapping_description && cachedData.mapping_description !== 'null'
        ? cachedData.mapping_description
        : '';

      this.prepareRuleManagerData();
    },

    async getExportConfigurationMapping() {
      try {
        this.showLoading();
        const response = await exportApiService.getExportConfigurationMapping(
          this.inforM3TomlMappingId,
        );

        if (!response.success) {
          throw { message: response.data.message };
        }

        this.toml_rules = decodeURIComponent(response.data.mapping_value);

        this.prepareRuleManagerData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async updateTomlConfig() {
      try {
        if (this.isDefault) {
          return;
        }

        if (this.isNameRequired) {
          const nameInput = this.$refs.nameInputRef as any;
          if (nameInput) {
            nameInput.validate();
            if (nameInput.hasError) {
              return;
            }
          }
        }

        this.showLoading();
        let response: any;
        if (this.inforM3TomlMappingId) {
          response = await exportApiService.updateTomlConfig(
            this.inforM3TomlMappingId,
            this.toml_rules,
          );
        } else {
          const formData = new FormData();
          formData.append('type', M3_TOML_MAPPING);
          formData.append('mapping_name', this.name);
          formData.append('mapping_value', this.toml_rules);
          formData.append(
            'mapping_description',
            this.description && this.description !== 'null' ? this.description : ''
          );

          if (this.id) {
            formData.append('mapping_id', this.id);
          }

          response =
            await exportApiService.duplicateTomlMappingSamples(formData);

          if (response.data && response.data.id) {
            this.id = response.data.id;

            // update data in cache
            this.updateCacheData();
          }
        }

        if (!response.success) {
          throw { message: response.data.message };
        }

        notify.success(this.$t('MSG_SAVE'));

        // Update the visual rules view with the saved TOML
        this.prepareRuleManagerData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    updateCacheData() {
      const cachedData = this.getDataFromSessionByKey(RULE_MANAGER) as any;

      if (!cachedData) {
        return;
      }
      cachedData.id = this.id;
      cachedData.mapping_name = this.name;
      cachedData.mapping_value = this.toml_rules;
      cachedData.mapping_description = this.description;

      this.setDataToSessionStorage(RULE_MANAGER, cachedData);
    },

    prepareRuleManagerData() {
      this.json_rules = toml.parse(this.toml_rules);
      this.rules = this.json_rules.conflict_resolution.rule;

      if (this.selectedIndex >= 0 && this.rules[this.selectedIndex]) {
        this.selectedRule = this.rules[this.selectedIndex];
      }
    },
    updateToml() {
      this.toml_rules = stringifyToml(this.json_rules);
    },
    addExampleCode() {
      this.toml_rules = `
[[rules]]
      `;
    },

    highlighter(code: any) {

      return highlight(code, languages.python, 'python'); // languages.<insert language> to return html with markup
    },
    ruleClick(rule: any, index: number) {
      this.selectedRule = rule;
      this.selectedIndex = index;

      if (!this.selectedRule.match_criteria) {
        this.selectedRule.match_criteria = [];
      }

      if (!this.selectedRule.actions) {
        this.selectedRule.actions = [];
      }

      this.preapreUpdateModel();
    },
    preapreUpdateModel() {
      this.rule_name = this.selectedRule.name;
      this.sectionModel = this.selectedRule.section;
    },
    removeRule(index: number) {
      const isCurrentRow = this.selectedIndex === index;
      this.rules.splice(index, 1);
      this.updateToml();

      if (isCurrentRow) {
        this.resetModel();
      } else if (this.selectedIndex > index) {
        this.selectedIndex -= 1;
      }
    },
    addRule() {
      if (!this.rule_name) {
        notify.error(
          this.$t('please_enter_rule_name'),
        );
        return;
      }

      const rule: any = {
        name: this.rule_name,
        section: this.sectionModel,
        active: true,
        match_criteria: [],
        actions: [],
      };
      this.rules.push(rule);

      this.updateToml();
      this.resetModel();
    },
    updateRule() {
      if (!this.selectedIndex) {
        return;
      }

      this.rules[this.selectedIndex].name = this.rule_name;
      this.rules[this.selectedIndex].section = this.sectionModel;

      this.updateToml();
      this.resetModel();
    },
    resetModel() {
      this.rule_name = '';
      this.sectionModel = 'cost_lines';
      this.selectedRule = null;
      this.selectedIndex = -1;
    },
    changeAction() {
      if (this.headerCheckbox === true) {
        this.selectAllRows();
      } else {
        this.resetAllSelectedRows();
      }
    },
    resetAllSelectedRows() {
      this.selectionList = [];
      this.headerCheckbox = false;

      this.rules.forEach((row: any) => {
        row['active'] = false;
      });
    },
    selectAllRows() {
      this.rules.forEach((row: any) => {
        row['active'] = true;
      });
    },
    toggleMenu() {
      this.showExportPanel = !this.showExportPanel;
    },
    async loadExportJson() {
      try {
        if (!this.docId) {
          return;
        }

        let response = await documentDetailApiService.getInforExportApiJson(
          this.docId,
        );
        if (!response || !response.success) {
          throw response;
        }
        this.exportJson = response.data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
  setup() {
    const export_store = useDocExportStore();
    const {} = storeToRefs(export_store);
    const { getTomlFile } = useDocExportStore();

    const settings_store = useSettingStore();
    const { loading_settings, user_settings } = storeToRefs(settings_store);

    const rule_manager_store = useRuleManagerStore();
    rule_manager_store.$reset();

    const { selectedRule } = storeToRefs(rule_manager_store);

    return {
      actions: ref([]),
      rule_name: ref(''),
      tolerance: ref(''),
      headerCheckbox: ref(false),
      inforM3TomlMappingId: ref(''),
      sectionModel: ref('cost_lines'),
      action_type_options: ref([]),
      section_options: ref([] as any),

      rules: ref([] as any),
      showActivityPanel: ref(true),
      splitterModel: ref(65),
      selectionList: ref([] as any),
      exportJson: ref([] as any),
      selectedIndex: ref(-1),

      toml_rules: ref('' as any),
      json_rules: ref({} as any),
      showExportPanel: ref(false),

      loading_settings,
      user_settings,
      selectedRule,
      getTomlFile,
    };
  },
});
</script>

<style scoped>
.rule-management-height {
  height: calc(100vh - 140px) !important;
}

.rule-manage-select {
  min-width: 23%;
}

.actions-select {
  min-width: 12%;
}

.test-rules-input {
  width: 90%;
}

.special-rules-editor {
  /* we dont use `language-` classes anymore so thats why we need to add background and text color manually */
  background: #2d2d2d;
  color: #ccc;

  /* you must provide font-family font-size line-height. Example: */
  font-family:
    Fira code,
    Fira Mono,
    Consolas,
    Menlo,
    Courier,
    monospace;
  font-size: 14px;
  line-height: 1.5;
  padding: 5px;
  min-height: 200px;
  height: 100%;
}


</style>
